  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Faux. L'AMF rappelle que si le client ne communique pas les informations sur sa situation, ses connaissances et ses objectifs, le conseiller doit s'abstenir de tout conseil, quel que soit le niveau de risque du support. Voir la leçon 1, « Explication simple ».$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
