  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 2, $academy_seed$L'écoute est réussie quand le conseiller peut restituer la situation, les projets, l'horizon et le rapport au risque et que le client valide cette restitution. Une signature ou une présentation du cabinet n'en sont pas la preuve. Voir la leçon 1, « En rendez-vous ».$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l1, $academy_seed$q04$academy_seed$, $academy_seed$cas_court$academy_seed$, $academy_seed$Préparer la découverte$academy_seed$, $academy_seed$Cas fictif. Madame Roux, pharmacienne, déclare en découverte : « Je veux du rendement, mais je ne veux surtout pas perdre. » Que faites-vous ?$academy_seed$, $academy_seed$["Noter « profil équilibré » et passer à la question suivante.","Expliquer que rendement et risque sont liés, puis retenir un profil dynamique puisqu'elle veut du rendement.","Proposer un fonds en euros pour lever le doute immédiatement.","Explorer la contradiction : demander ce qu'elle ferait si son épargne baissait de 10 % sur un an, quel montant elle peut immobiliser, et pour quel projet."]$academy_seed$::jsonb, 2)
