  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 3, $academy_seed$Une contradiction apparente est une information à creuser, pas à trancher. Le rapport au risque se recueille par des questions concrètes sur la réaction à une baisse, la capacité de perte et l'horizon, avant toute solution. Voir la leçon 1, « En rendez-vous ».$academy_seed$);
