  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 0, $academy_seed$Vrai. L'AMF indique que le professionnel doit envisager avec le client l'évolution de ses investissements dans un scénario défavorable, pour lui permettre de mesurer la perte possible. Une feuille de route qui ne montre que le scénario favorable est incomplète. Voir la leçon 2, « Explication simple ».$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l2, $academy_seed$q07$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Structurer l'analyse$academy_seed$, $academy_seed$Cas fictif. Après le premier entretien, le client vous écrit : « Envoyez-moi juste le bulletin de souscription, on verra l'étude plus tard. » Que faites-vous ?$academy_seed$, $academy_seed$["Envoyer le bulletin pour ne pas perdre le client ; l'étude suivra.","Faire signer une décharge de responsabilité, puis envoyer le bulletin.","Expliquer que l'étude chiffrée protège sa décision, proposer une date de restitution proche, et tracer l'échange.","Transmettre le dossier à un collègue plus expérimenté sans répondre."]$academy_seed$::jsonb, 3)
