  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 2, $academy_seed$Aucune recommandation ne précède l'étude. Le conseiller explique l'intérêt de l'étude pour le client, répond à la pression de calendrier par une date de restitution et trace la demande. Une décharge ne remplace pas l'analyse. Voir la leçon 2, « En rendez-vous ».$academy_seed$);
