  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 3, $academy_seed$Le point annuel détecte les changements de vie et vérifie l'adéquation de la stratégie. Arriver avec une solution à présenter transforme le suivi en rendez-vous de vente, ce que la leçon 3 identifie comme l'erreur fréquente.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l3, $academy_seed$q09$academy_seed$, $academy_seed$cas_court$academy_seed$, $academy_seed$Organiser le suivi$academy_seed$, $academy_seed$Cas fictif. Lors du point annuel, Monsieur Bellan annonce qu'il vendra son entreprise dans dix-huit mois et qu'il a changé de notaire. Quelle est la bonne suite ?$academy_seed$, $academy_seed$["Mettre à jour le bilan, demander son accord pour se coordonner avec le nouveau notaire et l'expert-comptable, et planifier une étude spécifique avant la vente.","Noter l'information et la reprendre lors du prochain point annuel.","Lui proposer dès maintenant une enveloppe pour accueillir le produit de la vente.","Lui conseiller de repousser la vente pour se laisser le temps d'organiser la fiscalité."]$academy_seed$::jsonb, 2)
